    return pd.read_csv(path, dtype=str)

def process(identityTheftByType, reportType) -> pd.DataFrame:
    import pandas as pd

    def norm(s):
        if s is None or (isinstance(s, float) and pd.isna(s)):
            return ''
        return str(s).strip().lower()

    it = identityTheftByType.copy()

    # Identify likely count/value column(s)
    count_candidates = [c for c in it.columns if norm(c) in {'count','counts','number','n','reports','report count','report_count','value','total'}]
    if not count_candidates:
        # fallback: choose the only numeric-like column after coercion
        numeric_scores = {}
        for c in it.columns:
            coerced = pd.to_numeric(it[c].str.replace(',','', regex=False), errors='coerce')
            numeric_scores[c] = coerced.notna().mean()
        best = max(numeric_scores, key=numeric_scores.get)
        count_col = best
    else:
        count_col = count_candidates[0]

    # Find theft type & subtype columns
    theft_type_col = None
    theft_subtype_col = None
    for c in it.columns:
        nc = norm(c)
        if theft_type_col is None and ('theft type' in nc or (nc == 'type' and 'report' not in nc)):
            theft_type_col = c
        if theft_subtype_col is None and ('theft subtype' in nc or 'subtype' in nc):
            theft_subtype_col = c

    # Fallback guesses if not found
    if theft_type_col is None:
        for c in it.columns:
            if it[c].astype(str).str.contains('bank', case=False, na=False).any():
                theft_type_col = c
                break
    if theft_subtype_col is None:
        for c in it.columns:
            if it[c].astype(str).str.contains('new account', case=False, na=False).any():
                theft_subtype_col = c
                break

    # Coerce counts
    it['_count_'] = pd.to_numeric(it[count_col].astype(str).str.replace(',','', regex=False), errors='coerce')

    # Numerator: identity theft reports with theft type Bank Account and subtype New Accounts
    num_mask = pd.Series(True, index=it.index)
    if theft_type_col is not None:
        num_mask &= it[theft_type_col].astype(str).str.strip().str.lower().eq('bank account')
    else:
        num_mask &= it.apply(lambda r: True, axis=1)  # no-op
    if theft_subtype_col is not None:
        num_mask &= it[theft_subtype_col].astype(str).str.strip().str.lower().eq('new accounts')
    numerator = it.loc[num_mask, '_count_'].sum(min_count=1)

    # Denominator: all reports (sum of counts in report type table)
    rt = reportType.copy()
    # choose count col similarly
    rt_count_candidates = [c for c in rt.columns if norm(c) in {'count','counts','number','n','reports','report count','report_count','value','total'}]
    if not rt_count_candidates:
        numeric_scores = {}
        for c in rt.columns:
            coerced = pd.to_numeric(rt[c].str.replace(',','', regex=False), errors='coerce')
            numeric_scores[c] = coerced.notna().mean()
        rt_count_col = max(numeric_scores, key=numeric_scores.get)
    else:
        rt_count_col = rt_count_candidates[0]

    rt['_count_'] = pd.to_numeric(rt[rt_count_col].astype(str).str.replace(',','', regex=False), errors='coerce')
    denominator = rt['_count_'].sum(min_count=1)

    prop = float(numerator / denominator) if denominator and pd.notna(denominator) else float('nan')

    return pd.DataFrame([{
        'numerator_identity_theft_bank_account_new_accounts': numerator,
        'denominator_all_reports': denominator,
        'proportion': round(prop, 4)
    }])

